import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, luminance, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {any} [intent]
 * @property {any} [visualSpec]
 * @property {any[]} [cinematicPrimitives]
 * @property {string[]} [textContent]
 * @property {any} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} emit
 * @property {any} fontAtlas
 * @property {Record<string, Function>} primitives
 * @property {string} [tier]
 */

/**
 * Creates a loop column gallery node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Vector3 } = ctx.THREE;

  const root = new Group();

  // ------- BACKDROP GRADIENT PLANE -------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradColorNode = mix(
    color(new Color('#0b0b10')),
    color(new Color('#14141a')),
    uv().y
  );
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: gradColorNode });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // ------- HEADLINE TEXT -------
  const headline = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: -0.005,
    lineHeight: 1.1,
  });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  // ------- PLATE SETUP -------
  const plateCount = 6;
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const pitch = 1.5;
  const columnOffsetX = 0.9;

  const plateGeom = new PlaneGeometry(plateWidth, plateHeight);
  const bevelGeom = new PlaneGeometry(plateWidth + 0.06, plateHeight + 0.06);
  const accentGeom = new PlaneGeometry(0.03, plateHeight);

  // Shared materials (will be cloned per mesh)
  const plateBaseMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.1,
    clearcoat: 0.1,
    transparent: true,
  });

  const bevelMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    roughness: 0.5,
    metalness: 0.5,
  });

  const accentMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.4,
  });

  const platesGroup = new Group();
  root.add(platesGroup);

  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const plateMeshes = [];
  const captionObjects = [];

  for (let i = 0; i < plateCount; i++) {
    const yPos = (i - (plateCount - 1) / 2) * pitch;

    // Bevel
    const bevel = new Mesh(bevelGeom, bevelMat.clone());
    bevel.position.set(columnOffsetX, yPos, 0);
    platesGroup.add(bevel);

    // Plate
    const plateMat = plateBaseMat.clone();
    const plate = new Mesh(plateGeom, plateMat);
    plate.position.set(columnOffsetX, yPos, 0.001);
    platesGroup.add(plate);
    plateMeshes.push({ mesh: plate, material: plateMat });

    // Accent strip (left edge)
    const accent = new Mesh(accentGeom, accentMat.clone());
    const accentX = columnOffsetX - plateWidth / 2 + 0.015;
    accent.position.set(accentX, yPos, 0.002);
    platesGroup.add(accent);

    // Caption text
    const caption = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'left',
      letterSpacing: 0.08,
      lineHeight: 1.4,
    });
    caption.position.set(-1.6, yPos, 0.003);
    root.add(caption);
    captionObjects.push(caption);
  }

  // Load texture and assign to plates
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      plateMeshes.forEach(({ material }) => {
        material.map = tex;
        material.needsUpdate = true;
      });
    });

  // ------- ANIMATION SETUP -------
  const timelines = [];

  // Focus scaling animation (placeholder, runs once on creation)
  const focusPlate = plateMeshes[0]; // nearest to y=0 initially
  const focusTL = gsap.timeline();
  focusTL.to(
    focusPlate.mesh.scale,
    {
      x: 1.06,
      y: 1.06,
      z: 1.06,
      duration: 0.35,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    },
    0
  );
  timelines.push(focusTL);

  // Caption fade‑in animation for the first plate (example)
  const captionTL = gsap.timeline();
  captionTL.fromTo(
    captionObjects[0].scale,
    { x: 0.9, y: 0.9, z: 0.9 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.5,
      ease: 'power2.out',
    },
    0
  );
  timelines.push(captionTL);

  // ------- CINEMATIC PRIMITIVES -------
  const primitiveCleanups = [];

  // Apply any listed cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const exec = fn(root, prim.params || {});
        if (exec && typeof exec.cleanup === 'function') {
          primitiveCleanups.push(exec.cleanup);
        }
      }
    }
  }

  // Ensure the required fly-through primitive is applied (trigger: scroll)
  const fly = ctx.primitives['fly-through'](root, { depthUnits: 2.5 });
  if (fly && typeof fly.cleanup === 'function') {
    primitiveCleanups.push(fly.cleanup);
  }

  // ------- USERDATA & CLEANUP -------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose timelines
    timelines.forEach((tl) => tl.kill());

    // Dispose materials and textures
    plateMeshes.forEach(({ material }) => {
      if (material.map) material.map.dispose();
      material.dispose();
    });
    bevelMat.dispose();
    accentMat.dispose();
    backdropMat.dispose();

    // Dispose geometries
    plateGeom.dispose();
    bevelGeom.dispose();
    accentGeom.dispose();
    backdropGeom.dispose();

    // Primitive cleanups
    primitiveCleanups.forEach((fn) => {
      try {
        fn();
      } catch (_) {}
    });
  };

  // Ensure texture promise does not block cleanup
  texturePromise.catch(() => {});

  return root;
}
